param([Parameter(Mandatory=$true)][string]$ArchivePath)
# Continuação NI: leitura de ZIP e verificação documental, sem código do aplicativo ou escrita remota.
$ErrorActionPreference='Stop'
if($PSScriptRoot){$repoRoot=Split-Path -Parent $PSScriptRoot}else{$repoRoot=(Get-Location).Path}
$checkpoint='dc51d86a6b3968f7c4d5489b44fcf73f34428a01'
$output=Join-Path $repoRoot 'validation/evidence/ni-source-transfer-validation.json'
$baseline=Get-Content -Raw -Encoding utf8 -LiteralPath (Join-Path $repoRoot 'validation/evidence/ni-source-transfer-baseline.json')|ConvertFrom-Json
$intake=Get-Content -Raw -Encoding utf8 -LiteralPath (Join-Path $repoRoot 'validation/evidence/ni-source-transfer-intake.json')|ConvertFrom-Json
$issues=New-Object System.Collections.Generic.List[string]
$allowedModified=@('README.md','AGENTS.md','governance/SOURCE-MANIFEST.md','governance/SOURCE-RECONCILIATION.md','governance/AUTHORITY-MODEL.md','governance/PROJECT-INSTRUCTIONS.md','governance/RAG-PROTOCOL.md','status/CURRENT-STATUS.md','status/RISK-REGISTER.md','validation/KNOWLEDGE-READINESS.md','validation/M01-NORMATIVE-TRACEABILITY.md','validation/M01-ACCEPTANCE-CRITERIA.md','status/NORMATIVE-CONFLICT-REGISTER.md','product/M01-PRODUCT-BASELINE.md','product/M01-FUNCTIONAL-REQUIREMENTS.md','context/PROJECT-CONTEXT.md','decisions/DECISION-REGISTER.md','engineering/REQUIREMENT-REGISTER.md','planning/WORK-PACKAGE-REGISTER.md','planning/M01-ROADMAP.md')
$allowedNew=@('governance/sources/m01-mvp-original-mandate-01.md','governance/sources/m01-directory-construction-mandate-01.md','governance/sources/project-instructions-authoritative.md','governance/sources/project-instructions-extended-historical.md','governance/sources/product-planner-mandate.md','governance/reviews/planner-m01-normative-review-01.md','governance/reviews/cto-source-transfer-01.md','validation/VAL-NI-SOURCE-TRANSFER-01.md','status/NI-SOURCE-TRANSFER-HANDOFF.md','validation/validate-ni-source-transfer.ps1','validation/evidence/ni-source-transfer-baseline.json','validation/evidence/ni-source-transfer-intake.json','validation/evidence/ni-source-transfer-validation.json')
$preserved=@()
foreach($f in $baseline.files){$target=Join-Path $repoRoot $f.path;if(-not (Test-Path -LiteralPath $target)){$issues.Add('Arquivo inicial excluído: '+$f.path);continue};if($allowedModified -notcontains $f.path){$after=(Get-FileHash -Algorithm SHA256 -LiteralPath $target).Hash.ToLower();$same=$after -eq $f.sha256;$preserved+=@{path=$f.path;before_sha256=$f.sha256;after_sha256=$after;unchanged=$same};if(-not $same){$issues.Add('Histórico alterado: '+$f.path)}}}
Add-Type -AssemblyName System.IO.Compression.FileSystem
if(-not ('AncestralidadeTransferCrc32' -as [type])){Add-Type -TypeDefinition 'public static class AncestralidadeTransferCrc32 { public static uint Compute(byte[] a) { uint c=0xffffffffu; foreach(byte b in a){c^=b; for(int i=0;i<8;i++)c=(c&1u)!=0?0xedb88320u^(c>>1):c>>1;} return c^0xffffffffu;} }'}
$zipBytes=[System.IO.File]::ReadAllBytes($ArchivePath);$zipSha=(Get-FileHash -Algorithm SHA256 -LiteralPath $ArchivePath).Hash.ToLower()
if($zipSha -ne $intake.archive_sha256){$issues.Add('ZIP difere do pacote recebido no intake')}
$utf8=New-Object System.Text.UTF8Encoding($false,$true);$eocd=-1
for($i=$zipBytes.Length-22;$i -ge [Math]::Max(0,$zipBytes.Length-65557);$i--){if([BitConverter]::ToUInt32($zipBytes,$i) -eq 0x06054b50){$eocd=$i;break}}
if($eocd -lt 0){throw 'Diretório central ZIP não reconhecido'}
$entryCount=[BitConverter]::ToUInt16($zipBytes,$eocd+10);$offset=[int][BitConverter]::ToUInt32($zipBytes,$eocd+16);$expectedCrc=@{}
for($i=0;$i -lt $entryCount;$i++){if([BitConverter]::ToUInt32($zipBytes,$offset) -ne 0x02014b50){throw 'Diretório central inválido'};$nl=[BitConverter]::ToUInt16($zipBytes,$offset+28);$xl=[BitConverter]::ToUInt16($zipBytes,$offset+30);$cl=[BitConverter]::ToUInt16($zipBytes,$offset+32);$name=$utf8.GetString($zipBytes,$offset+46,$nl);$expectedCrc[$name]=[BitConverter]::ToUInt32($zipBytes,$offset+16);$offset+=46+$nl+$xl+$cl}
$sourceTexts=@{};$zipResults=@();$archive=[System.IO.Compression.ZipFile]::OpenRead($ArchivePath)
try{if($archive.Entries.Count -ne 6 -or $entryCount -ne 6){$issues.Add('ZIP não contém seis entradas')};foreach($entry in $archive.Entries){$record=$intake.entries|Where-Object entry -eq $entry.FullName;if(-not $record){throw 'Entrada ZIP não permitida'};$s=$entry.Open();$mem=New-Object System.IO.MemoryStream;try{$s.CopyTo($mem);$data=$mem.ToArray()}finally{$s.Dispose();$mem.Dispose()};$text=$utf8.GetString($data);$crc=[AncestralidadeTransferCrc32]::Compute($data);$sha=[System.Security.Cryptography.SHA256]::Create();try{$hash=([BitConverter]::ToString($sha.ComputeHash($data))).Replace('-','').ToLower()}finally{$sha.Dispose()};$lineCount=($text -split "`n").Count;if($text.EndsWith("`n")){$lineCount--};$canonical=Join-Path $repoRoot $record.canonical_path;$copy=[System.IO.File]::ReadAllText($canonical);$copyHash=(Get-FileHash -Algorithm SHA256 -LiteralPath $canonical).Hash.ToLower();$pass=$crc -eq $expectedCrc[$entry.FullName] -and $hash -eq $record.source_sha256 -and $data.Length -eq $record.bytes -and $lineCount -eq $record.lines -and $copyHash -eq $record.canonical_sha256 -and $copy.EndsWith($text);if(-not $pass){$issues.Add('Integridade/cópia divergente: '+$record.source)};$zipResults+=@{source=$record.source;entry=$entry.FullName;bytes=$data.Length;lines=$lineCount;sha256=$hash;crc32=('{0:x8}'-f $crc);crc_pass=($crc -eq $expectedCrc[$entry.FullName]);utf8_strict_pass=$true;canonical_sha256=$copyHash;integral_text_preserved=$copy.EndsWith($text);result=$(if($pass){'PASS'}else{'FAIL'})};$sourceTexts[$record.source]=$text}}
finally{$archive.Dispose()}
$originalCriteria=@([regex]::Matches($sourceTexts['SOURCE-01'],'(?m)^## (AC-\d{2}) — ([^\r\n]+)\r?\n\r?\n([^\r\n]+)'))
$proposedCriteria=@([regex]::Matches($sourceTexts['SOURCE-02'],'(?m)^\| (AC-\d{2}) \| ([^\r\n|]+) \|'))
if($originalCriteria.Count -ne 18 -or $proposedCriteria.Count -ne 26){$issues.Add('Quantidade de critérios de origem divergente')}
$originalSections=[regex]::Matches($sourceTexts['SOURCE-01'],'(?m)^# \d+\.').Count;$constructionSections=[regex]::Matches($sourceTexts['SOURCE-02'],'(?m)^# \d+\.').Count
if($originalSections -ne 32 -or $constructionSections -ne 28){$issues.Add('Quantidade de seções divergente')}
$docs=@(Get-ChildItem -Recurse -File -LiteralPath $repoRoot -Filter '*.md'|Where-Object {$_.FullName -notmatch '[\\/]\.git[\\/]'})
$ids=@{};$references=0
foreach($f in $docs){$rel=$f.FullName.Substring($repoRoot.Length+1).Replace('\','/');$t=[System.IO.File]::ReadAllText($f.FullName);$header=[regex]::Match($t,'(?s)\A---\r?\n(.*?)\r?\n---\r?\n');if(-not $header.Success){$issues.Add('Frontmatter ausente: '+$rel);continue};$m=$header.Groups[1].Value
 foreach($k in @('id','title','version','status','authority','maintainer','module','classification','references','supersedes','last_updated')){if($m -notmatch ('(?m)^'+$k+':\s*')){$issues.Add('Metadata ausente: '+$rel+' / '+$k)}}
 $id=[regex]::Match($m,'(?m)^id:\s*(\S+)').Groups[1].Value;if($ids.ContainsKey($id)){$issues.Add('ID duplicado: '+$id)}else{$ids[$id]=$rel}
 if($m -notmatch '(?m)^classification: PUBLIC\s*$'){$issues.Add('Classificação não pública: '+$rel)}
 if($t.Contains([char]0xFFFD)){$issues.Add('Caractere de substituição: '+$rel)}
 if(([regex]::Matches($t,'(?m)^```').Count % 2) -ne 0){$issues.Add('Code fence não fechado: '+$rel)}
 $targets=@([regex]::Matches($t.Substring($header.Length),'\]\(([^)]+)\)')|ForEach-Object {$_.Groups[1].Value});$targets+=@([regex]::Matches($m,'(?m)^  - "([^"\r\n]+)"\s*$')|ForEach-Object {$_.Groups[1].Value})
 foreach($target in $targets){if($target -match '^(https?:|mailto:|#)'){continue};$references++;$path=[System.IO.Path]::GetFullPath((Join-Path $f.DirectoryName (($target.Trim('<','>') -split '#',2)[0])));if($path -eq $output){continue};if(-not (Test-Path -LiteralPath $path)){$issues.Add('Referência inexistente: '+$rel+' -> '+$target)}}
 foreach($pattern in @('gh[pousr]_[A-Za-z0-9]{30,}','github_pat_[A-Za-z0-9_]{40,}','AKIA[0-9A-Z]{16}','-----BEGIN (RSA |EC |OPENSSH )?PRIVATE KEY-----','\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b','\b\d{3}\.\d{3}\.\d{3}-\d{2}\b','C:[\\/]Users[\\/]')){if([regex]::IsMatch($t,$pattern,[System.Text.RegularExpressions.RegexOptions]::IgnoreCase)){$issues.Add('Padrão sensível, conteúdo omitido: '+$rel)}}
 if($allowedModified -contains $rel){$prev=[regex]::Match($m,'(?m)^previous_revision: "([^"\r\n]+)"').Groups[1].Value;if(-not $prev.StartsWith($checkpoint+':'+$rel+'@')){$issues.Add('Revisão anterior não atualizada: '+$rel)};$v=($prev-split '@')[-1];$parts=$v.Split('.');$expected=$parts[0]+'.'+([int]$parts[1]+1);$current=[regex]::Match($m,'(?m)^version: "([^"]+)"').Groups[1].Value;if($current -ne $expected){$issues.Add('Versão não incrementada: '+$rel)}}
}
$trace=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'validation/M01-NORMATIVE-TRACEABILITY.md'))
$mvRows=[regex]::Matches($trace,'(?m)^\| MVP:AC-\d{2} \(§27\) \|').Count;$coRows=[regex]::Matches($trace,'(?m)^\| CONSTRUCTION:AC-\d{2} \(§20\) \|').Count
if($mvRows -ne 18 -or $coRows -ne 26){$issues.Add('Namespaces ou contagens da matriz incorretos')}
if([regex]::Matches($trace,'(?m)^\| MVP:AC-\d{2} \(§27\) \|[^\r\n]*\| UNRESOLVED \|').Count -ne 18){$issues.Add('Destino pendente das 18 origens deve ser explícito')}
$tests=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'validation/M01-ACCEPTANCE-CRITERIA.md'))
$testRows=@([regex]::Matches($tests,'(?m)^\| (MVP:AC-\d{2}) \| ([^\r\n|]+) \| ([^\r\n|]+) \| ([^\r\n|]+) \|'))
if($testRows.Count -ne 18){$issues.Add('Plano de testes não cobre os 18 MVP:AC')}
foreach($m in $originalCriteria){$id='MVP:'+$m.Groups[1].Value;$row=$testRows|Where-Object {$_.Groups[1].Value -eq $id};if(-not $row -or $row.Groups[2].Value.Trim() -ne $m.Groups[3].Value.Trim() -or -not $row.Groups[3].Value.Trim() -or -not $row.Groups[4].Value.Trim()){$issues.Add('Texto/positivo/negativo ausente ou alterado: '+$id)}}
$manifest=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'governance/SOURCE-MANIFEST.md'));foreach($r in $intake.entries){if(-not $manifest.Contains($r.source_sha256) -or -not $manifest.Contains($r.canonical_sha256)){$issues.Add('Hashes ausentes no manifesto: '+$r.source)}}
if(-not $manifest.Contains($zipSha)){$issues.Add('Hash do pacote ausente no manifesto')}
$role03=$intake.entries|Where-Object source -eq 'SOURCE-03';$role03A=$intake.entries|Where-Object source -eq 'SOURCE-03A';$role02=$intake.entries|Where-Object source -eq 'SOURCE-02'
if($role03.source_role -ne 'CURRENT_PROJECT_INSTRUCTIONS' -or $role03A.source_role -ne 'HISTORICAL_REFERENCE_ONLY' -or $role02.source_status -ne 'PROPOSED_FOR_EXECUTIVE_AUTHORIZATION'){$issues.Add('Vigência ou proposta de origem indevidamente promovida')}
$state=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'status/CURRENT-STATUS.md'))
foreach($s in @('6/9','4/7','PARTIALLY_SATISFIED','SOURCE-06','SOURCE-07','SOURCE-09','CTO','NORMATIVE_DIRECTION_APPROVED','NOT_FROZEN','NOT_PREPARED','NOT_ESTABLISHED','CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW')){if(-not $state.Contains($s)){$issues.Add('Estado corrente incompleto: '+$s)}}
$val=[System.IO.File]::ReadAllText((Join-Path $repoRoot 'validation/VAL-NI-SOURCE-TRANSFER-01.md'));$criteria=@([regex]::Matches($val,'(?m)^\| (AC-NI-\d{2}) \|[^\r\n]*? \| (PASS|FAIL|BLOCKED|NOT_EXECUTED) \|')|ForEach-Object {@{id=$_.Groups[1].Value;result=$_.Groups[2].Value}})
$counts=@{};foreach($s in @('PASS','FAIL','BLOCKED','NOT_EXECUTED')){$counts[$s]=@($criteria|Where-Object result -eq $s).Count}
if($criteria.Count -ne 16 -or $counts.PASS -ne 9 -or $counts.FAIL -ne 0 -or $counts.BLOCKED -ne 7 -or $counts.NOT_EXECUTED -ne 0){$issues.Add('Matriz AC-NI da retomada inconsistente')}
foreach($id in @('AC-NI-02','AC-NI-03','AC-NI-04')){if(@($criteria|Where-Object {$_.id -eq $id -and $_.result -eq 'PASS'}).Count -ne 1){$issues.Add('Recepção efetiva não refletida: '+$id)}}
foreach($id in @('AC-NI-05','AC-NI-07','AC-NI-08','AC-NI-09','AC-NI-10','AC-NI-12','AC-NI-13')){if(@($criteria|Where-Object {$_.id -eq $id -and $_.result -eq 'BLOCKED'}).Count -ne 1){$issues.Add('Dependência CTO não refletida: '+$id)}}
foreach($p in @('governance/mandates/m01-consolidated-mandate-1.0.md','governance/mandates/m01-consolidated-mandate-1.1.md','governance/reviews/cto-m01-normative-review-02.md')){if(Test-Path -LiteralPath (Join-Path $repoRoot $p)){$issues.Add('Intake mudou; gate/validação requerem atualização: '+$p)}}
$head=(& git -C $repoRoot rev-parse HEAD).Trim();if($head -ne $checkpoint){$issues.Add('HEAD mudou durante retomada')}
$changes=@(& git -C $repoRoot status --porcelain=v1 --untracked-files=all | ForEach-Object {$_.Substring(3).Replace('\','/')});foreach($p in $changes){if($allowedModified -notcontains $p -and $allowedNew -notcontains $p){$issues.Add('Arquivo fora do escopo: '+$p)}}
$result=[ordered]@{id='ANCESTRALIDADE-VAL-NI-SOURCE-TRANSFER-LOCAL-RESULT';date='2026-11-27';executor='AGENT_CODER';checkpoint=$checkpoint;head=$head;archive=@{name=[System.IO.Path]::GetFileName($ArchivePath);bytes=$zipBytes.Length;sha256=$zipSha;entries=$zipResults;entry_count=$zipResults.Count;crc_errors=@($zipResults|Where-Object crc_pass -ne $true).Count;utf8_strict='PASS'};required_sources=@{available=6;total=9;essential_available=4;essential_total=7;historical_extra='SOURCE-03A';pending_cto=@('SOURCE-06','SOURCE-07','SOURCE-09');planner_transfer='COMPLETE'};markdown_files=$docs.Count;unique_ids=$ids.Count;references_checked=$references;historical_files_preserved=$preserved.Count;preservation=$preserved;original_sections=$originalSections;construction_sections=$constructionSections;MVP_criteria=$originalCriteria.Count;CONSTRUCTION_proposed_criteria=$proposedCriteria.Count;positive_negative_test_design_rows=$testRows.Count;application_tests='NOT_EXECUTED';traceability=@{pending_MVP_rows=18;provisional_UNRESOLVED=18;completed_original_to_consolidated_comparisons=0;reverse_coverage='NOT_EVALUATED_SOURCE_06_PENDING'};ac_ni=$criteria;counts=$counts;previous_validators_or_evidence_reexecuted=$false;cto_planner_tests_attributed_to_agent=$false;revision_1_1='NOT_PREPARED';C10='OPEN';AC_KF_03_R1='BLOCKED';T01='NORMATIVE_DIRECTION_APPROVED';errors=@($issues);result=$(if($issues.Count -eq 0){'PASS'}else{'FAIL'});delivery='EXECUTED_WITH_SOURCE_TRANSFER_BLOCKER';limitations=@('Integrity of received bytes is not equivalence with unavailable historical records or a signature','Consolidated mandate, presidential deliberation and CTO normative review not received','No application tests or independent remote validation of this uncommitted intake','Pattern, Markdown and metadata checks are not exhaustive legal, YAML or rendering validation','Byte hashes are evidence of this session; checkout may normalize line endings');next_gate='CTO_NORMATIVE_BASELINE_INTEGRATION_REVIEW'}
[System.IO.File]::WriteAllText($output,($result|ConvertTo-Json -Depth 12),(New-Object System.Text.UTF8Encoding($false)))
if(-not (Test-Path -LiteralPath $output)){throw 'Evidência de saída não gravada'}
[pscustomobject]@{result=$result.result;zip_entries=$zipResults.Count;crc_errors=$result.archive.crc_errors;markdown_files=$docs.Count;unique_ids=$ids.Count;references_checked=$references;historical_files_preserved=$preserved.Count;MVP_criteria=$originalCriteria.Count;CONSTRUCTION_proposed_criteria=$proposedCriteria.Count;counts=$counts;errors=@($issues)}|ConvertTo-Json -Depth 6
if($issues.Count -gt 0){throw 'Validação da transferência falhou; consulte evidence/ni-source-transfer-validation.json'}
